using Microsoft.Data.Sqlite;
using System.Diagnostics;
using System.Globalization;
using System.Text.Json;
namespace TagPrinter;

/// <summary>Isolated physical-inventory checks for frozen scope, identity conflicts, durable queues, reconciliation and full recovery.</summary>
internal static class CountTests
{
    /// <summary>Runs real SQLite and UI cases without a scanner, printer, application accounts or real user records.</summary>
    internal static void Run(string folder)
    {
        Ui.Language="en";string root=Path.Combine(folder,"physical-counts-"+Guid.NewGuid());Directory.CreateDirectory(root);var history=new HistoryStore(Path.Combine(root,"inventory.db"));var assets=new AssetStore(history);var store=new CountStore(history);
        AssetRecord Asset(string serial,string place,string status="Available")=>assets.Save(new AssetRecord{AssetType="Laptop",Brand="Dell",Model="Latitude",Serial=serial,Location=place,Status=status});
        var a=Asset("000001","HQ");var b=Asset("000002","HQ");var noSerial=Asset("","HQ");var wrong=Asset("000003","Branch");var retired=Asset("000004","HQ","Retired");var codeSerial=Asset("TP-00000099","HQ");var session=store.Create("Annual check"," hq ","Frozen; \"scope\"\nlocal count");if(session.ExpectedCount!=4 || session.Location!="HQ" || store.Results(session.Id).Totals.Pending!=4)throw new Exception("Count location normalization/frozen scope failed");
        var found=store.Scan(session.Id,"Serial"," 000001 ");var duplicate=store.Scan(session.Id,"Serial","000001");if(found.Result!="Found" || duplicate.Duplicate!=true || store.Results(session.Id).Totals.Found!=1 || store.Results(session.Id).Totals.Duplicates!=1)throw new Exception("Repeated readings inflated physical assets");
        if(store.Scan(session.Id,"Serial","000003").Result!="WrongLocation" || store.Scan(session.Id,"Serial","000004").Result!="Retired" || store.Scan(session.Id,"Serial","BAD_%").Result!="Unknown" || store.Scan(session.Id,"AssetCode",noSerial.Code).Result!="Found" || store.Scan(session.Id,"Serial",codeSerial.Serial).Entry.AssetUid!=codeSerial.Uid || store.Scan(session.Id,"AssetCode",codeSerial.Serial).Result!="Unknown")throw new Exception("Physical reading classifications/explicit identifier modes failed");
        if(assets.Get(wrong.Uid)!.Location!="Branch" || history.Count()!=0)throw new Exception("Physical count changed a master or label history");
        a=assets.Save(a with {Serial="RENAMED"});if(store.Scan(session.Id,"Serial","RENAMED").Entry.AssetUid!=a.Uid)throw new Exception("Current serial did not resolve the frozen expected identity");var reused=Asset("000001","HQ");if(store.Scan(session.Id,"Serial","000001").Result!="Ambiguous" || store.Scan(session.Id,"AssetCode",reused.Code).Result!="Unexpected" || store.Scan(session.Id,"Serial","000001").Result!="Ambiguous")throw new Exception("Reused/frozen serial silently counted a different asset");
        var revision=store.Get(session.Id)!.Revision;var missing=store.Results(session.Id).Rows.Single(r=>r.Entry.AssetUid==a.Uid);store.Undo(session.Id,missing.Entry.Id,revision);if(store.Results(session.Id).Totals.Found!=2)throw new Exception("Undo did not return expected asset to pending");store.Scan(session.Id,"AssetCode",a.Code);var unknown=store.Results(session.Id,"Unknown","BAD_%").Rows.Single();store.Undo(session.Id,unknown.Entry.Id,store.Get(session.Id)!.Revision);if(store.Results(session.Id,"Unknown","BAD_%").Total!=0 || store.Results(session.Id,"Withdrawn","BAD_%").Total!=1)throw new Exception("Withdrawn unknown remained active or lost evidence");store.Scan(session.Id,"Serial","BAD_%");
        Reject<InvalidOperationException>(()=>store.Finish(session.Id,1));Reject<InvalidDataException>(()=>store.Scan(session.Id,"Serial",""));Reject<InvalidDataException>(()=>store.Scan(session.Id,"Serial","A\nB"));
        // Asset edits after capture cannot rewrite the reconciliation baseline.
        assets.Save(b with {Location="Elsewhere"});assets.Save(wrong with {Location="HQ"});var closed=store.Finish(session.Id,store.Get(session.Id)!.Revision);var final=store.Results(session.Id);if(final.Totals.Expected!=4 || final.Totals.Found!=3 || final.Totals.Pending!=1 || store.Results(session.Id,"Missing").Rows.Single().Entry.AssetUid!=b.Uid || store.Results(session.Id,"WrongLocation").Rows.Single().Entry.Snapshot!.Location!="Branch")throw new Exception("Frozen scope/missing/wrong-location evidence drifted");Reject<InvalidOperationException>(()=>store.Scan(session.Id,"Serial","000002"));Reject<InvalidOperationException>(()=>store.Undo(session.Id,found.Entry.Id,closed.Revision));
        var canceled=store.Create("Canceled walk","HQ");canceled=store.Finish(canceled.Id,canceled.Revision,true);if(store.Results(canceled.Id,"Missing").Total!=0 || store.Results(canceled.Id).Rows.Any(r=>r.Outcome=="Missing"))throw new Exception("Canceled count incorrectly declares missing assets");
        string csv=Path.Combine(root,"results.csv");if(store.ExportCsv(csv,session.Id)!=final.Total)throw new Exception("Result CSV did not include all scoped records");using(var parser=new Microsoft.VisualBasic.FileIO.TextFieldParser(csv,System.Text.Encoding.UTF8)){parser.SetDelimiters(";");parser.HasFieldsEnclosedInQuotes=true;var header=parser.ReadFields()!;string[] row;do{row=parser.ReadFields()!;}while(row[6]!=a.Uid && !parser.EndOfData);if(header.Length!=23 || row[8]!="000001" || row[21]!=session.Notes || row[15]!="Found")throw new Exception("Count CSV changed frozen leading zeros, notes or results");}
        using(var cancel=new CancellationTokenSource()){cancel.Cancel();File.WriteAllText(csv,"keep");Reject<OperationCanceledException>(()=>store.ExportCsv(csv,session.Id,token:cancel.Token));if(File.ReadAllText(csv)!="keep")throw new Exception("Canceled count CSV replaced destination");}
        string audit=Path.Combine(root,"readings.csv");if(store.ExportActionsCsv(audit,session.Id)!=store.Actions(session.Id).Total)throw new Exception("Count action export scope mismatch");
        TestScale(root,history,store);TestBackups(root,history,store,session.Id);TestMigration(root,history);TestUi(folder,root,history,assets.Get(a.Uid)!);
        File.WriteAllText(Path.Combine(folder,"counts-results.txt"),"PASS: frozen exact-location scope; explicit serial/asset-code modes; Unicode/literal identities; duplicate/unknown/retired/wrong-location/unexpected outcomes; reused serial ambiguity guards; withdrawal audit; terminal missing versus canceled/pending; stale/closed write rejection; 10000-asset bounded/indexed sessions/results/action pages; atomic rollback and semantic backup validation; protected schema-4 and legacy restore; quoted/canceled full CSV; actual bilingual/minimum-size/async UI; FIFO order, retained failed head/retry and close guard. Local, no RFID or printer jobs.");Ui.Language="en";
    }
    /// <summary>Seeds an isolated 10000-asset scope in one transaction; validates bounded pages, duplicate-heavy audit plans and transactional failure.</summary>
    private static void TestScale(string root,HistoryStore history,CountStore store)
    {
        using(var c=history.Open())using(var tx=c.BeginTransaction())using(var cmd=c.CreateCommand())
        {
            cmd.Transaction=tx;string now=DateTimeOffset.UtcNow.ToString("O",CultureInfo.InvariantCulture);cmd.Parameters.AddWithValue("$json",JsonSerializer.Serialize(new AssetRecord{Revision=1,AssetType="Scale",Location="Scale",CreatedUtc=now,UpdatedUtc=now}));cmd.CommandText="""
                WITH RECURSIVE n(i) AS(SELECT 1000001 UNION ALL SELECT i+1 FROM n WHERE i<1010000)
                INSERT INTO assets(id,uid,serial_key,revision,record_json) SELECT i,printf('%032x',i),printf('S%08d',i),1,json_set($json,'$.Uid',printf('%032x',i),'$.Number',i,'$.Serial',printf('S%08d',i)) FROM n;
                """;cmd.ExecuteNonQuery();tx.Commit();
        }
        var scale=store.Create("Scale walk","Scale");var first=store.Results(scale.Id);var second=store.Results(scale.Id,page:1);if(scale.ExpectedCount!=10000 || first.Rows.Count!=50 || second.Rows.Count!=50 || first.Rows.Select(r=>r.Entry.Id).Intersect(second.Rows.Select(r=>r.Entry.Id)).Any())throw new Exception("Physical count materialized the full registry or overlapping pages");string serial=first.Rows[0].Entry.Snapshot!.Serial;for(int i=0;i<53;i++)store.Scan(scale.Id,"Serial",serial);if(store.Results(scale.Id).Totals.Found!=1 || store.Results(scale.Id).Totals.Duplicates!=52 || store.Actions(scale.Id).Rows.Count!=50 || store.Actions(scale.Id,1).Rows.Count!=4)throw new Exception("Duplicate-heavy count/action paging failed");
        using(var c=history.Open())using(var cmd=c.CreateCommand()){cmd.CommandText="EXPLAIN QUERY PLAN SELECT id FROM count_entries WHERE session_id="+scale.Id+" AND asset_uid IS NOT NULL AND lookup_key!='' AND lookup_key='S01000001'";using var reader=cmd.ExecuteReader();bool indexed=false;while(reader.Read())if(reader.GetString(3).Contains("ix_count_frozen_serial"))indexed=true;if(!indexed)throw new Exception("Count frozen-serial lookup scans instead of indexing");}
        long before=store.Actions(scale.Id).Total;int revision=store.Get(scale.Id)!.Revision;Sql(history.DatabasePath,"CREATE TRIGGER fail_count_audit BEFORE INSERT ON count_actions WHEN NEW.action='Seen' BEGIN SELECT RAISE(ABORT,'synthetic write failure');END;");Reject<SqliteException>(()=>store.Scan(scale.Id,"Serial",second.Rows[0].Entry.Snapshot!.Serial));Sql(history.DatabasePath,"DROP TRIGGER fail_count_audit;");if(store.Actions(scale.Id).Total!=before || store.Get(scale.Id)!.Revision!=revision || store.Results(scale.Id).Totals.Found!=1)throw new Exception("Failed count audit partially committed");
        using(var c=history.Open())CountStore.ValidateDatabase(c);
    }
    /// <summary>Full restores preserve sessions/snapshots/effective states/actions, and reject readable SQLite with broken count evidence.</summary>
    private static void TestBackups(string root,HistoryStore history,CountStore store,long closedId)
    {
        string backup=Path.Combine(root,"complete.db");history.Backup(backup);var added=store.Create("Later count","HQ");history.RestoreBackup(backup,Path.Combine(root,"restore-safety"));if(store.Get(added.Id)!=null || store.Results(closedId,"Missing").Total!=1 || store.Get(closedId)!.Status!="Closed")throw new Exception("Full count backup/restore lost reconciliation");
        string bad=Path.Combine(root,"corrupt-count.db");history.Backup(bad);Sql(bad,"UPDATE count_sessions SET expected_count=expected_count+1 WHERE id="+closedId);Reject<InvalidDataException>(()=>history.RestoreBackup(bad,Path.Combine(root,"rejected")));if(store.Results(closedId,"Missing").Total!=1)throw new Exception("Corrupt count replaced live data");history.Backup(bad);Sql(bad,"UPDATE count_actions SET input_value='BROKEN' WHERE id=(SELECT MIN(id) FROM count_actions WHERE action='Seen')");Reject<InvalidDataException>(()=>HistoryStore.ValidateBackup(bad));history.Backup(bad);Sql(bad,"DELETE FROM count_actions WHERE session_id="+closedId+" AND revision=(SELECT MAX(revision) FROM count_actions WHERE session_id="+closedId+")");Reject<InvalidDataException>(()=>HistoryStore.ValidateBackup(bad));
    }
    /// <summary>Builds a real schema-4 file and verifies protected upgrade plus staged old-backup restoration without mutating source.</summary>
    private static void TestMigration(string root,HistoryStore history)
    {
        string directory=Path.Combine(root,"legacy4");Directory.CreateDirectory(directory);string path=Path.Combine(directory,"inventory.db");history.Backup(path);Sql(path,"DROP TABLE count_actions;DROP TABLE count_entries;DROP TABLE count_sessions;PRAGMA user_version=4;");var upgraded=new HistoryStore(path);string safety=Directory.GetFiles(Path.Combine(directory,"backups"),"TagPrinter-before-counts-*.db").Single();if(Scalar(path,"PRAGMA user_version")!="5" || Scalar(safety,"PRAGMA user_version")!="4")throw new Exception("Protected physical-count migration failed");new HistoryStore(path);if(Directory.GetFiles(Path.Combine(directory,"backups"),"TagPrinter-before-counts-*.db").Length!=1)throw new Exception("Count migration repeated");upgraded.RestoreBackup(safety,Path.Combine(directory,"restore-safety"));if(new CountStore(upgraded).Sessions().Total!=0 || Scalar(safety,"PRAGMA user_version")!="4")throw new Exception("Schema-4 staged restore modified its source or retained future counts");
    }
    /// <summary>Exercises actual dialog bindings, scanner FIFO/close protection/failure retry, asynchronous pages and translated minimum-size layout.</summary>
    private static void TestUi(string folder,string root,HistoryStore history,AssetRecord asset)
    {
        CountSession created;using(var dialog=new NewCountDialog(history))
        {
            dialog.Show();dialog.Controls.Find("CountName",true).Single().Text="Warehouse verification";dialog.Controls.Find("CountLocation",true).Single().Text="HQ";Save(dialog,folder,"new-count-en.png");var creating=dialog.CreateAsync();Pump(()=>creating.IsCompleted);if(!creating.GetAwaiter().GetResult())throw new Exception("Actual count-creation form failed");created=dialog.CreatedSession!;
        }
        using var form=new MainForm(Path.Combine(root,"ui-settings.json"),AppConfig.CreateDefault(),history.DatabasePath);form.Show();form.ShowCounts();var view=form.Counts;view.ForceAsyncReads=true;view.OpenSession(created.Id);Pump(()=>view.ResultsGrid.Rows.Count>0);var input=(TextBox)view.Controls.Find("CountScanner",true).Single();input.Text=new string('X',121);if(input.MaxLength<121 || view.Enqueue("Serial",input.Text) || input.Text.Length!=121)throw new Exception("Oversized scanner input was truncated or silently accepted");input.Clear();if(!view.Enqueue("AssetCode",asset.Code) || !view.Enqueue("AssetCode",asset.Code) || !view.Enqueue("Serial","UI-UNKNOWN"))throw new Exception("Scanner FIFO did not accept input");form.Close();if(form.IsDisposed)throw new Exception("Normal close silently abandoned queued readings");Pump(()=>!view.HasPendingWork);view.RefreshResults();Pump(()=>view.ResultsGrid.Rows.Count>0 && view.ResultsGrid.Enabled);if(new CountStore(history).Results(created.Id).Totals.Duplicates!=1)throw new Exception("Queued duplicate inflated results");
        Sql(history.DatabasePath,"CREATE TRIGGER ui_count_failure BEFORE INSERT ON count_actions WHEN NEW.action='Seen' BEGIN SELECT RAISE(ABORT,'temporary count failure');END;");view.Enqueue("Serial","RETRY-HEAD");view.Enqueue("Serial","RETRY-TAIL");Pump(()=>view.QueuePaused);Save(form,folder,"count-queue-retry-en.png");if(view.Queued!=2)throw new Exception("Failed FIFO lost or skipped an unsaved input");Sql(history.DatabasePath,"DROP TRIGGER ui_count_failure;");view.RetryQueue();Pump(()=>!view.HasPendingWork);var actions=new CountStore(history).Actions(created.Id).Rows.Where(a=>a.Action=="Seen").OrderBy(a=>a.Revision).Select(a=>a.InputValue).ToArray();if(actions[^2]!="RETRY-HEAD" || actions[^1]!="RETRY-TAIL")throw new Exception("Retry changed FIFO order");
        view.RefreshResults();Pump(()=>view.ResultsReady && view.ResultsGrid.Rows.Count>=8);Save(form,folder,"physical-count-en.png");form.Restore(form.CaptureWork() with {Language="es"});form.ShowCounts();Pump(()=>view.ResultsReady && view.ResultsGrid.Rows.Count>=8);Save(form,folder,"physical-count-es.png");form.Size=form.MinimumSize;Save(form,folder,"physical-count-small-es.png");if(view.ResultsGrid.Width<450 || view.ResultsGrid.Height<100)throw new Exception("Physical count grid unusable at minimum size");form.Size=new Size(1160,850);form.Restore(form.CaptureWork() with {Language="en"});view.OpenSession(1);Pump(()=>view.ResultsReady);Save(form,folder,"physical-count-closed-en.png");form.Close();Ui.Language="en";
    }
    /// <summary>Captures actual off-screen controls without using user desktop coordinates.</summary>
    private static void Save(Form form,string folder,string name){Application.DoEvents();using var image=new Bitmap(form.Width,form.Height);form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(Path.Combine(folder,name));}
    /// <summary>Pumps the real synchronization context with a bounded wait.</summary>
    private static void Pump(Func<bool> done){var watch=Stopwatch.StartNew();while(!done() && watch.ElapsedMilliseconds<20000){Application.DoEvents();Thread.Sleep(5);}if(!done())throw new Exception("Count UI operation timed out");}
    /// <summary>Mutates only the explicit isolated test database.</summary>
    private static void Sql(string path,string sql){using var c=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=path,Pooling=false}.ToString());c.Open();using var cmd=c.CreateCommand();cmd.CommandText=sql;cmd.ExecuteNonQuery();}
    /// <summary>Reads fixture metadata without migration or user-state access.</summary>
    private static string Scalar(string path,string sql){using var c=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=path,Pooling=false}.ToString());c.Open();using var cmd=c.CreateCommand();cmd.CommandText=sql;return Convert.ToString(cmd.ExecuteScalar(),CultureInfo.InvariantCulture)!;}
    /// <summary>Requires an expected failure rather than accepting silent success.</summary>
    private static void Reject<T>(Action action) where T:Exception{try{action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
}
